def tostring(self, language=Language.C):
    if language is Language.Fortran:
        return {RelOp.EQ: '.eq.', RelOp.NE: '.ne.',
                RelOp.LT: '.lt.', RelOp.LE: '.le.',
                RelOp.GT: '.gt.', RelOp.GE: '.ge.'}[self]
    return {RelOp.EQ: '==', RelOp.NE: '!=',
            RelOp.LT: '<', RelOp.LE: '<=',
            RelOp.GT: '>', RelOp.GE: '>='}[self]

